package gin

import (
	"errors"
	"fmt"
	"testing"
)

func TestZZZUnwrapProbe(t *testing.T) {
	inner := errors.New("inner probe error")

	valWrapped := fmt.Errorf("wrapped: %w", Error{Err: inner, Type: ErrorTypeAny})
	ptrWrapped := fmt.Errorf("wrapped: %w", &Error{Err: inner, Type: ErrorTypeAny})

	if !errors.Is(valWrapped, inner) {
		t.Errorf("errors.Is failed for Error VALUE: got false, want true")
	}
	if !errors.Is(ptrWrapped, inner) {
		t.Errorf("errors.Is failed for *Error POINTER: got false, want true")
	}
	if errors.Unwrap(valWrapped) == nil {
		t.Errorf("errors.Unwrap returned nil for Error VALUE")
	}

	var valTarget *Error
	if !errors.As(valWrapped, &valTarget) {
		t.Errorf("errors.As failed for Error VALUE")
	}
	var ptrTarget *Error
	if !errors.As(ptrWrapped, &ptrTarget) {
		t.Errorf("errors.As failed for *Error POINTER")
	}

	t.Logf("errors.Is(value)=%v errors.Is(pointer)=%v errors.As(value)=%v errors.As(pointer)=%v",
		errors.Is(valWrapped, inner), errors.Is(ptrWrapped, inner), errors.As(valWrapped, &valTarget), errors.As(ptrWrapped, &ptrTarget))
}

package gin

import (
	"errors"
	"fmt"
	"testing"
)

type zzzProbeErr string

func (e zzzProbeErr) Error() string { return string(e) }

func TestZZZUnwrapProbe(t *testing.T) {
	inner := zzzProbeErr("inner probe error")

	valWrapped := fmt.Errorf("wrapped: %w", Error{Err: inner, Type: ErrorTypeAny})
	ptrWrapped := fmt.Errorf("wrapped: %w", &Error{Err: inner, Type: ErrorTypeAny})

	if !errors.Is(valWrapped, inner) {
		t.Errorf("errors.Is failed for Error VALUE: got false, want true")
	}
	if !errors.Is(ptrWrapped, inner) {
		t.Errorf("errors.Is failed for *Error POINTER: got false, want true")
	}
	if errors.Unwrap(valWrapped) == nil {
		t.Errorf("errors.Unwrap returned nil for Error VALUE")
	}

	var valTarget zzzProbeErr
	if !errors.As(valWrapped, &valTarget) {
		t.Errorf("errors.As failed for Error VALUE")
	}
	var ptrTarget zzzProbeErr
	if !errors.As(ptrWrapped, &ptrTarget) {
		t.Errorf("errors.As failed for *Error POINTER")
	}

	// errors.As to *Error works for the pointer case (and for the value case only
	// if the value is addressable through a pointer in the chain).
	var ptrGinErr *Error
	if !errors.As(ptrWrapped, &ptrGinErr) {
		t.Errorf("errors.As(*Error) failed for *Error POINTER")
	}

	t.Logf("errors.Is(value)=%v errors.Is(pointer)=%v errors.As(value)=%v errors.As(pointer)=%v",
		errors.Is(valWrapped, inner), errors.Is(ptrWrapped, inner), errors.As(valWrapped, &valTarget), errors.As(ptrWrapped, &ptrTarget))
}

