func TestTmpCIProbe(t *testing.T) {
	cases := []struct {
		routes []string
		lookup string
	}{
		{[]string{"/user/:id", "/users"}, "/USER/123"},
		{[]string{"/foo/:bar", "/foobar"}, "/FOOBAR"},
		{[]string{"/foo/:bar", "/foobar"}, "/FOO/XYZ"},
		{[]string{"/user/:id", "/users"}, "/USERS"},
	}
	for _, c := range cases {
		tree := &node{}
		for _, r := range c.routes {
			tree.addRoute(r, tmpHandlers())
		}
		func() {
			defer func() {
				if r := recover(); r != nil {
					fmt.Printf("routes=%v lookup=%q PANIC: %v\n", c.routes, c.lookup, r)
				}
			}()
			p, ok := tree.findCaseInsensitivePath(c.lookup, false)
			fmt.Printf("routes=%v lookup=%q -> path=%q ok=%v\n", c.routes, c.lookup, string(p), ok)
		}()
	}
}

