	"testing"
)

func tryNegotiate(c *Context, offered ...string) (res string, panicked any) {
	defer func() {
		if r := recover(); r != nil {
			panicked = r
		}
	}()
	res = c.NegotiateFormat(offered...)
	return
}

func TestZZZNegotiateProbe(t *testing.T) {
	cases := []struct {
		accept  string
		offered []string
	}{
		{"", []string{MIMEJSON, MIMEXML}},
		{"*/*", []string{MIMEJSON, MIMEXML}},
		{"text/*", []string{MIMEHTML, MIMEJSON}},
		{"text/html", []string{"text"}},                          // offer shorter than accepted
		{"application/json", []string{"application"}},            // offer shorter than accepted
		{"application/json", []string{"application/json", "text"}},
		{"text/html", []string{"text/htm"}},
		{"text/html", []string{"text/html; charset=utf-8"}},      // offer longer
		{"application/xhtml+xml", []string{MIMEHTML, MIMEJSON}},
		{"text/html,application/xhtml+xml,application/xml;q=0.9;q=0.8", []string{MIMEJSON, MIMEXML}},
	}
	for _, tc := range cases {
		c, _ := CreateTestContext(httptest.NewRecorder())
		c.Request, _ = http.NewRequest("POST", "/", nil)
		if tc.accept != "" {
			c.Request.Header.Add("Accept", tc.accept)
		}
		res, pan := tryNegotiate(c, tc.offered...)
		t.Logf("accept=%-55q offered=%-40q -> result=%q panic=%v", tc.accept, fmt.Sprint(tc.offered), res, pan)
	}
}

